UPDATE tools SET faq = $x$[{"q": "מהי AdCreative.ai?", "a": "AdCreative.ai היא פלטפורמת AI שנבנתה במיוחד ליצירת קריאייטיבים פרסומיים. היא יוצרת תמונות מודעה, כותרות ותוכן טקסטואלי המותאמים להמרה עבור Facebook, Google, Instagram ופלטפורמות נוספות. היא מדרגת כל קריאייטיב לפי ביצועים חזויים כדי לעזור לכם לבחור את הגרסאות הטובות ביותר."}, {"q": "האם AdCreative.ai שווה את זה?", "a": "עבור עסקים המריצים תקציבי פרסום משמעותיים בתשלום, AdCreative.ai יכולה לחסוך זמן עיצוב משמעותי ולשפר את ביצועי הפרסום באמצעות יצירת קריאייטיב ממוטב בבינה מלאכותית. עבור תקציבים קטנים או עסקים שמריצים מודעות מדי פעם, תבניות הפרסום של Canva עשויות להספיק במחיר נמוך יותר."}, {"q": "האם Canva טובה למודעות?", "a": "Canva טובה לעיצוב תמונות מודעה באמצעות תבניות וכלי בינה מלאכותית. עם זאת, Canva אינה ממטבת לביצועי פרסום ואינה חוזה שיעורי קליקים. AdCreative.ai נבנתה במיוחד עבור פרסום עם חיזוי ביצועים. לעיצוב מודעה מהיר, Canva מתאימה; לאופטימיזציית ביצועים, AdCreative.ai מתמחה יותר."}, {"q": "כמה עולה AdCreative.ai?", "a": "ל-AdCreative.ai אין תוכנית חינמית, רק תקופת ניסיון חינמית בת 7 ימים. התוכניות בתשלום הן Starter ב-39 דולר לחודש (10 קרדיטים בחודש, מותג אחד, משתמש אחד), Professional ב-249 דולר לחודש (50 קרדיטים בחודש, עד 10 מותגים, 10 משתמשים), ו-Ultimate ב-999 דולר לחודש (100 קרדיטים בחודש, עד 25 מותגים, 20 משתמשים), בנוסף לתמחור Enterprise מותאם אישית. הנחות של 25% חלות על חיוב רבעוני ו-50% על חיוב שנתי."}]$x$::jsonb
 WHERE slug = 'adcreative-ai' AND lang = 'he';

