UPDATE tools SET faq = $x$[{"q": "Qu'est-ce qu'AdCreative.ai ?", "a": "AdCreative.ai est une plateforme IA spécifiquement conçue pour générer des créations publicitaires. Elle génère des images publicitaires, des titres et des textes optimisés pour la conversion sur Facebook, Google, Instagram et d'autres plateformes. Elle évalue chaque création selon sa performance prédite pour vous aider à choisir les meilleures variantes."}, {"q": "AdCreative.ai en vaut-il la peine ?", "a": "Pour les entreprises gérant des budgets publicitaires payants importants, AdCreative.ai peut faire gagner un temps de conception considérable et améliorer la performance publicitaire grâce à une génération de créations optimisées par IA. Pour de petits budgets ou des entreprises faisant des publicités occasionnelles, les modèles publicitaires de Canva peuvent suffire à moindre coût."}, {"q": "Canva est-il adapté pour les publicités ?", "a": "Canva convient bien pour concevoir des visuels publicitaires à l'aide de modèles et d'outils IA. Cependant, Canva n'optimise pas la performance publicitaire et ne prédit pas les taux de clics. AdCreative.ai est spécifiquement conçu pour la publicité avec prédiction de performance. Pour une conception publicitaire rapide, Canva fonctionne bien ; pour l'optimisation de la performance, AdCreative.ai est plus spécialisé."}, {"q": "Combien coûte AdCreative.ai ?", "a": "AdCreative.ai ne propose pas de forfait gratuit, uniquement un essai gratuit de 7 jours. Les forfaits payants sont Starter à 39 $/mois (10 crédits/mois, 1 marque, 1 utilisateur), Professional à 249 $/mois (50 crédits/mois, jusqu'à 10 marques, 10 utilisateurs) et Ultimate à 999 $/mois (100 crédits/mois, jusqu'à 25 marques, 20 utilisateurs), ainsi qu'une tarification Enterprise personnalisée. Des remises de 25 % s'appliquent pour la facturation trimestrielle et de 50 % pour la facturation annuelle."}]$x$::jsonb
 WHERE slug = 'adcreative-ai' AND lang = 'fr';

