UPDATE tools SET faq = $x$[{"q": "O que é a AdCreative.ai?", "a": "A AdCreative.ai é uma plataforma de IA construída especificamente para gerar criativos publicitários. Ela gera imagens, títulos e textos de anúncios otimizados para conversão no Facebook, Google, Instagram e outras plataformas. Ela pontua cada criativo pelo desempenho previsto para ajudar você a escolher as melhores variantes."}, {"q": "Vale a pena usar a AdCreative.ai?", "a": "Para empresas que executam orçamentos significativos de publicidade paga, a AdCreative.ai pode economizar bastante tempo de design e melhorar o desempenho dos anúncios por meio da geração de criativos otimizados por IA. Para orçamentos pequenos ou empresas que fazem anúncios ocasionais, os modelos de anúncio do Canva podem ser suficientes a um custo menor."}, {"q": "O Canva é bom para anúncios?", "a": "O Canva é bom para projetar visuais de anúncios usando modelos e ferramentas de IA. No entanto, o Canva não otimiza para desempenho de anúncios nem prevê taxas de cliques. A AdCreative.ai é feita especificamente para publicidade, com previsão de desempenho. Para design rápido de anúncios, o Canva funciona; para otimização de desempenho, a AdCreative.ai é mais especializada."}, {"q": "Quanto custa a AdCreative.ai?", "a": "A AdCreative.ai não tem plano gratuito, apenas um teste gratuito de 7 dias. Os planos pagos são Starter, a US$ 39/mês (10 créditos/mês, 1 marca, 1 usuário), Professional, a US$ 249/mês (50 créditos/mês, até 10 marcas, 10 usuários), e Ultimate, a US$ 999/mês (100 créditos/mês, até 25 marcas, 20 usuários), além de preço Enterprise personalizado. Descontos de 25% se aplicam para cobrança trimestral e de 50% para cobrança anual."}]$x$::jsonb
 WHERE slug = 'adcreative-ai' AND lang = 'pt';

