UPDATE tools SET faq = $x$[{"q": "Що таке Hex?", "a": "Hex — це платформа для спільної роботи з даними, яка поєднує SQL-блокноти, Python і no-code графіки в єдиному робочому просторі. Команди з обробки даних використовують її для аналізу даних і створення інтерактивних застосунків даних. Hex agent пише SQL і Python на основі природної мови, пояснює код і автоматично генерує візуалізації, а спробувати його можна на безкоштовному плані Community."}, {"q": "Яка різниця між Looker Studio та Hex?", "a": "Looker Studio створює візуальні дашборди методом перетягування — це інструмент звітності для бізнес-користувачів. Hex — це блокнот даних і конструктор застосунків для команд, які працюють з SQL і Python. Looker Studio призначений лише для читання візуальної звітності; Hex — для інтерактивного аналізу та обчислень."}, {"q": "Скільки коштує Hex?", "a": "Hex пропонує безкоштовний план Community з обмеженими обчислювальними потужностями та спільними колекціями. План Professional коштує $36 за Editor на місяць, а план Team — $75 за Editor на місяць. Ціни на Enterprise індивідуальні та включають опційне додаткове місце Explorer. Обчислення на GPU для ML-навантажень оплачуються окремо погодинно."}]$x$::jsonb
