UPDATE tools SET faq = $x$[{"q": "מהי Hex?", "a": "Hex היא פלטפורמת נתונים שיתופית המשלבת מחברות SQL, Python ותרשימים ללא קוד בסביבת עבודה אחת. צוותי נתונים משתמשים בה לניתוח נתונים ובניית אפליקציות נתונים אינטראקטיביות. סוכן Hex כותב SQL ו-Python משפה טבעית, מסביר קוד, ומייצר תרשימים אוטומטית, וניתן לנסות אותו בתוכנית Community החינמית."}, {"q": "מה ההבדל בין Looker Studio ל-Hex?", "a": "Looker Studio יוצרת לוחות מחוונים חזותיים בגרירה ושחרור — זהו כלי דיווח למשתמשים עסקיים. Hex היא מחברת נתונים וכלי בניית אפליקציות לצוותי נתונים העובדים ב-SQL וב-Python. Looker Studio היא דיווח חזותי לקריאה בלבד; Hex היא ניתוח וחישוב אינטראקטיביים."}, {"q": "כמה עולה Hex?", "a": "Hex מציעה תוכנית Community חינמית עם חישוב ואוספים משותפים מוגבלים. תוכנית Professional עולה $36 למשתמש Editor לחודש, ותוכנית Team עולה $75 למשתמש Editor לחודש. תמחור Enterprise הוא מותאם אישית וכולל תוסף מושב Explorer אופציונלי. חישוב GPU לעומסי עבודה של למידת מכונה מחויב בנפרד לפי שעה."}]$x$::jsonb
