 WHERE slug = 'hex' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Hex ?", "a": "Hex est une plateforme de données collaborative combinant des notebooks SQL, Python et des graphiques sans code dans un seul espace de travail. Les équipes data l'utilisent pour analyser des données et créer des applications de données interactives. L'agent Hex écrit du SQL et du Python à partir du langage naturel, explique le code et génère automatiquement des visualisations, et peut être testé sur le plan gratuit Community."}, {"q": "Quelle est la différence entre Looker Studio et Hex ?", "a": "Looker Studio crée des tableaux de bord visuels par glisser-déposer — c'est un outil de reporting pour les utilisateurs métier. Hex est un notebook de données et un créateur d'applications pour les équipes data qui travaillent en SQL et Python. Looker Studio est un reporting visuel en lecture seule ; Hex est une analyse et un calcul interactifs."}, {"q": "Combien coûte Hex ?", "a": "Hex propose un plan Community gratuit avec un calcul et des collections partagées limités. Le plan Professional est à 36 $ par Editor et par mois, et le plan Team est à 75 $ par Editor et par mois. La tarification Enterprise est personnalisée et inclut un module optionnel de siège Explorer. Le calcul GPU pour les charges de travail de ML est facturé séparément à l'heure."}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'fr';

