UPDATE tools SET faq = $x$[{"q": "O que é o Hex?", "a": "Hex é uma plataforma colaborativa de dados que combina notebooks SQL, Python e gráficos no-code em um único espaço de trabalho. Equipes de dados a utilizam para analisar dados e criar apps de dados interativos. O Hex agent escreve SQL e Python a partir de linguagem natural, explica código e gera visualizações automaticamente, podendo ser testado no plano gratuito Community."}, {"q": "Qual é a diferença entre Looker Studio e Hex?", "a": "O Looker Studio cria dashboards visuais do tipo arrastar e soltar — é uma ferramenta de relatórios para usuários de negócios. O Hex é um construtor de notebooks e apps de dados para equipes que trabalham com SQL e Python. O Looker Studio é um relatório visual somente leitura; o Hex é análise e computação interativas."}, {"q": "Quanto custa o Hex?", "a": "O Hex oferece um plano gratuito Community com computação e coleções compartilhadas limitadas. O plano Professional custa US$ 36 por Editor por mês, e o plano Team custa US$ 75 por Editor por mês. O preço do Enterprise é personalizado e inclui um complemento opcional de assento Explorer. A computação em GPU para cargas de trabalho de ML é cobrada separadamente por hora."}]$x$::jsonb
