UPDATE tools SET faq = $x$[{"q": "Що таке Koyfin?", "a": "Koyfin — це платформа фінансових даних та аналітики, що позиціонується як доступна альтернатива Bloomberg Terminal. Вона надає фундаментальні дані, фінансові графіки, ринкові дані, відстеження портфелів та інструменти скринінгу для індивідуальних інвесторів, RIA та інвестиційних професіоналів."}, {"q": "Чи безкоштовний Koyfin?", "a": "Koyfin має безкоштовний план за $0/місяць з обмеженим функціоналом (2 роки фінансових даних, 2 списки спостереження, 2 скрини та інше). Платні плани — Plus за $39/місяць та Premium за $79/місяць, а також Advisor Core за $209/місяць та Advisor Pro за $299/місяць для фінансових консультантів. Річна оплата пропонує додаткову економію."}]$x$::jsonb
