UPDATE tools SET faq = $x$[{"q": "O que é o OpenCode?", "a": "OpenCode é um agente de codificação de IA de código aberto criado pela Anomaly, disponível como interface de terminal, aplicativo desktop e extensão de IDE. Ele suporta mais de 75 provedores de LLM através do Models.dev, incluindo Claude, GPT, Gemini e modelos locais. O agente principal é gratuito — você usa suas próprias chaves de API ou faz login com uma conta GitHub Copilot ou ChatGPT Plus/Pro."}, {"q": "O OpenCode é gratuito?", "a": "O próprio agente OpenCode é gratuito e de código aberto — você paga apenas pelas chamadas de API de LLM que fizer ao provedor escolhido, ou nada, caso utilize modelos locais. A Anomaly também oferece o OpenCode Zen, um gateway pago opcional para modelos selecionados, cobrado por requisição via créditos pré-pagos, além de um nível Enterprise com preços não divulgados."}, {"q": "Qual é a diferença entre o OpenCode e o Aider?", "a": "O Aider é um agente de codificação focado no terminal, com um histórico mais longo e forte integração com git. O OpenCode é mais recente e agora está disponível como interface de terminal, aplicativo desktop e extensão de IDE, com suporte a mais de 75 provedores de LLM via Models.dev. Ambos são de código aberto — vale testar os dois para ver qual fluxo de trabalho se encaixa melhor."}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'pt';

