UPDATE tools SET faq = $x$[{"q": "¿Qué es Retool?", "a": "Retool es una plataforma low-code para construir herramientas internas. Los desarrolladores se conectan a bases de datos y APIs, y luego crean paneles de administración, dashboards y apps CRUD usando componentes de arrastrar y soltar. A diferencia de los dashboards, las apps de Retool pueden realizar acciones — editar registros de bases de datos, activar flujos de trabajo, enviar datos."}, {"q": "¿Es gratis Retool?", "a": "Retool tiene un plan gratuito para hasta 5 usuarios, pero está limitado por consumo: 500 ejecuciones de flujos de trabajo, 5 GB de capacidad de base de datos, 5 GB de almacenamiento de archivos, 250 créditos de IA y hasta 20 horas de agente al mes. Los planes de pago separan los puestos de Builder e Internal User: los puestos Team Builder cuestan 10 $/usuario/mes facturado anualmente (12 $/usuario/mes facturado mensualmente), los puestos Business Builder cuestan 50 $/usuario/mes anualmente (65 $ mensualmente), y el precio de Enterprise es personalizado."}, {"q": "¿Es Retool una herramienta no-code?", "a": "Retool es low-code en lugar de no-code. Requiere ciertos conocimientos técnicos — conectarse a bases de datos, escribir consultas SQL y entender APIs. Está diseñado para desarrolladores y equipos técnicos, no para usuarios de negocio sin formación técnica."}]$x$::jsonb
