UPDATE tools SET faq = $x$[{"q": "Was ist Retool?", "a": "Retool ist eine Low-Code-Plattform zum Erstellen interner Tools. Entwickler verbinden sich mit Datenbanken und APIs und erstellen dann Admin-Panels, Dashboards und CRUD-Apps mithilfe von Drag-and-Drop-Komponenten. Im Gegensatz zu Dashboards können Retool-Apps Aktionen ausführen — Datenbankeinträge bearbeiten, Workflows auslösen, Daten senden."}, {"q": "Ist Retool kostenlos?", "a": "Retool bietet einen kostenlosen Plan für bis zu 5 Nutzer, dieser ist jedoch nutzungsabhängig begrenzt: 500 Workflow-Ausführungen, 5 GB Datenbankkapazität, 5 GB Dateispeicher, 250 KI-Credits und bis zu 20 Agenten-Stunden pro Monat. Kostenpflichtige Pläne trennen Builder-Plätze und Internal-User-Plätze: Team-Builder-Plätze kosten 10 $/Nutzer/Monat bei jährlicher Abrechnung (12 $/Nutzer/Monat bei monatlicher Abrechnung), Business-Builder-Plätze kosten 50 $/Nutzer/Monat bei jährlicher Abrechnung (65 $ bei monatlicher Abrechnung), und die Enterprise-Preise sind individuell."}, {"q": "Ist Retool ein No-Code-Tool?", "a": "Retool ist eher Low-Code als No-Code. Es erfordert gewisse technische Kenntnisse — die Anbindung an Datenbanken, das Schreiben von SQL-Abfragen und das Verständnis von APIs. Es ist für Entwickler und technische Teams konzipiert, nicht für Geschäftsanwender ohne technischen Hintergrund."}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'de';

