UPDATE tools SET faq = $x$[{"q": "Що таке Retool?", "a": "Retool — це low-code платформа для створення внутрішніх інструментів. Розробники підключаються до баз даних і API, а потім створюють адмін-панелі, дашборди та CRUD-застосунки за допомогою компонентів drag-and-drop. На відміну від дашбордів, застосунки Retool можуть виконувати дії — редагувати записи в базі даних, запускати робочі процеси, надсилати дані."}, {"q": "Чи Retool безкоштовний?", "a": "Retool має безкоштовний план для до 5 користувачів, але з обмеженнями: 500 запусків робочих процесів, 5 ГБ ємності бази даних, 5 ГБ файлового сховища, 250 AI-кредитів та до 20 годин агента на місяць. Платні плани розділяють місця Builder і Internal User: місця Team Builder коштують $10/користувача/місяць за річної оплати ($12/користувача/місяць за щомісячної), місця Business Builder коштують $50/користувача/місяць за річної оплати ($65 за щомісячної), а ціни Enterprise — індивідуальні."}, {"q": "Чи є Retool no-code інструментом?", "a": "Retool є радше low-code, ніж no-code. Він вимагає певних технічних знань — підключення до баз даних, написання SQL-запитів і розуміння API. Він розроблений для розробників і технічних команд, а не для бізнес-користувачів без технічної підготовки."}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'ua';

