UPDATE tools SET faq = $x$[{"q": "מה זה Retool?", "a": "Retool היא פלטפורמת low-code לבניית כלים פנים-ארגוניים. מפתחים מתחברים למסדי נתונים וממשקי API, ואז בונים פאנלי ניהול, דשבורדים ואפליקציות CRUD בעזרת רכיבי drag-and-drop. בשונה מדשבורדים, אפליקציות Retool יכולות לבצע פעולות — לערוך רשומות במסד נתונים, להפעיל זרימות עבודה, לשלוח נתונים."}, {"q": "האם Retool חינמית?", "a": "ל-Retool יש תוכנית חינמית לעד 5 משתמשים, אך היא מוגבלת בשימוש: 500 הרצות זרימת עבודה, קיבולת מסד נתונים של 5GB, אחסון קבצים של 5GB, 250 קרדיטי AI, ועד 20 שעות סוכן בחודש. תוכניות בתשלום מפרידות בין מקומות Builder למקומות Internal User: מקומות Team Builder עולים $10 למשתמש לחודש בחיוב שנתי ($12 למשתמש לחודש בחיוב חודשי), מקומות Business Builder עולים $50 למשתמש לחודש בחיוב שנתי ($65 בחיוב חודשי), ותמחור Enterprise הוא מותאם אישית."}, {"q": "האם Retool הוא כלי no-code?", "a": "Retool הוא low-code ולא no-code. הוא דורש ידע טכני מסוים — התחברות למסדי נתונים, כתיבת שאילתות SQL, והבנת ממשקי API. הוא מיועד למפתחים ולצוותים טכניים, לא למשתמשים עסקיים בלי רקע טכני."}]$x$::jsonb
