UPDATE tools SET description = $x$Plateforme low-code pour créer des outils métier internes — tableaux de bord, panneaux d'administration, éditeurs de données — avec des composants IA et des workflows agentiques. Le plan gratuit couvre jusqu'à 5 utilisateurs ; les paliers payants distinguent les sièges Builder et Internal User, facturés mensuellement ou annuellement (sièges Team Builder à 10 $/mois en facturation annuelle ou 12 $/mois en facturation mensuelle ; sièges Business Builder à 50 $/mois en facturation annuelle ou 65 $/mois en facturation mensuelle).$x$
 WHERE slug = 'retool-ai' AND lang = 'fr';

UPDATE tools SET description_long = $x$Retool est une plateforme de développement low-code pour créer des applications métier internes — panneaux d'administration, tableaux de bord de données, outils de support client et workflows opérationnels — en se connectant directement aux bases de données et aux API.

Depuis 2026, Retool organise sa plateforme autour d'Agents, de Workflows et d'Apps. Les Retool Agents sont désormais un module complémentaire distinct pour les agents autonomes gérant le support client, l'analyse de données et l'automatisation des processus, facturés à l'heure et séparément des crédits IA inclus dans chaque plan. « Retool AI » désigne désormais de façon générale ces capacités d'IA plutôt qu'une ligne de produit distincte.

Retool AI permet aux équipes d'intégrer des composants alimentés par des LLM dans les applications : complétion de formulaires par IA, synthèse de données par IA, chatbots IA au sein de tableaux de bord internes, et workflows agentiques enchaînant plusieurs étapes IA avec des points de validation humaine. La plateforme se connecte à des sources de données telles que Postgres, MySQL, Snowflake, MongoDB, les API REST et GraphQL. Le générateur par glisser-déposer crée des interfaces tandis que des composants prédéfinis gèrent les scénarios courants. Les fonctionnalités clés incluent un générateur d'applications visuel, des connexions aux bases de données et API, des composants IA (génération de texte par LLM, assistants IA de formulaires), un générateur de workflows agentiques avec étapes de validation humaine, la prise en charge de JavaScript et Python pour la logique personnalisée, des journaux d'audit et un contrôle d'accès basé sur les rôles.

Le plan gratuit de Retool couvre jusqu'à 5 utilisateurs avec des applications web et mobiles illimitées, mais il est soumis à des quotas : 500 exécutions de workflows par mois, 5 Go de capacité de base de données, 5 Go de stockage de fichiers, 250 crédits IA par mois, et jusqu'à 20 heures d'agent par mois. Les plans payants séparent les sièges Builder (les personnes qui créent des applications) des sièges Internal User, moins chers (les personnes qui les utilisent uniquement). Les sièges Team Builder coûtent 10 $ par utilisateur et par mois en facturation annuelle ou 12 $ en facturation mensuelle ; les sièges Team Internal User coûtent 5 $ par utilisateur et par mois en facturation annuelle ou 7 $ en facturation mensuelle. Les sièges Business Builder coûtent 50 $ par utilisateur et par mois en facturation annuelle ou 65 $ en facturation mensuelle ; les sièges Business Internal User coûtent 15 $ par utilisateur et par mois en facturation annuelle ou 18 $ en facturation mensuelle. La tarification Enterprise est personnalisée. Les Retool Agents sont facturés séparément à l'heure, à des tarifs variant selon les capacités du modèle, avec un quota gratuit allant jusqu'à 20 heures d'agent par mois inclus dans tous les paliers.

Retool est optimisé pour les outils internes — il ne convient pas à la création d'applications de production destinées aux clients. Les agents IA sont facturés à l'heure en plus des coûts par siège, ce qui peut rendre les dépenses totales plus difficiles à prévoir pour les équipes qui utilisent les agents de façon intensive. Le générateur visuel, bien que puissant pour l'usage prévu par Retool, nécessite une certaine familiarité avec les concepts de données (requêtes, transformations) pour être utilisé efficacement.

Mieux adapté aux équipes opérationnelles, produit et ingénierie des startups et des entreprises qui doivent créer des outils internes personnalisés à partir de leurs sources de données existantes — en particulier celles qui ajoutent des workflows assistés par IA à leurs opérations métier existantes.$x$
 WHERE slug = 'retool-ai' AND lang = 'fr';

UPDATE tools SET pros = ARRAY[$x$Le générateur low-code réduit le temps de développement d'outils internes de plusieurs semaines à quelques jours$x$, $x$Se connecte directement aux bases de données (Postgres, MySQL, Snowflake, MongoDB) et aux API (REST, GraphQL) sans travail backend personnalisé$x$, $x$Les composants IA permettent des fonctionnalités alimentées par des LLM dans les applications internes sans développement IA personnalisé$x$, $x$Le plan gratuit pour jusqu'à 5 utilisateurs inclut des crédits IA et des heures d'agent, pas seulement la création d'applications de base$x$, $x$Points de validation humaine pour les workflows d'agents IA$x$]::text[]
 WHERE slug = 'retool-ai' AND lang = 'fr';

UPDATE tools SET cons = ARRAY[$x$Ne convient pas aux applications de production destinées aux clients$x$, $x$Les Retool Agents sont facturés séparément à l'heure au-delà d'un quota gratuit de 20 heures/mois, ajoutant un coût imprévisible en plus de la tarification par siège$x$, $x$Nécessite des connaissances en requêtes de données pour une utilisation efficace — ce n'est pas vraiment du no-code$x$, $x$La tarification sépare les sièges Builder et Internal User entre les paliers Team et Business, compliquant les estimations de coûts$x$, $x$Les sièges Business Builder coûtent 65 $/utilisateur/mois en facturation mensuelle (50 $/utilisateur/mois en facturation annuelle), coûteux pour les grandes équipes$x$]::text[]
 WHERE slug = 'retool-ai' AND lang = 'fr';

UPDATE tools SET choose_if = $x$["✅ Vous créez des outils internes — panneaux d'administration, tableaux de bord avec actions, applications CRUD pour votre équipe", "✅ Vous devez non seulement afficher des données mais aussi effectuer des actions : modifier des enregistrements, exécuter des requêtes, déclencher des workflows", "✅ Vous vous connectez directement à des bases de données (PostgreSQL, MySQL, MongoDB) et à des API internes", "✅ Vous êtes un développeur ou une équipe technique créant rapidement des logiciels internes personnalisés"]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Retool ?", "a": "Retool est une plateforme low-code pour créer des outils internes. Les développeurs se connectent à des bases de données et des API, puis créent des panneaux d'administration, des tableaux de bord et des applications CRUD à l'aide de composants glisser-déposer. Contrairement aux tableaux de bord, les applications Retool peuvent effectuer des actions — modifier des enregistrements de base de données, déclencher des workflows, envoyer des données."}, {"q": "Retool est-il gratuit ?", "a": "Retool propose un plan gratuit pour jusqu'à 5 utilisateurs, mais il est soumis à des quotas : 500 exécutions de workflows, 5 Go de capacité de base de données, 5 Go de stockage de fichiers, 250 crédits IA et jusqu'à 20 heures d'agent par mois. Les plans payants séparent les sièges Builder et Internal User : les sièges Team Builder coûtent 10 $/utilisateur/mois en facturation annuelle (12 $/utilisateur/mois en facturation mensuelle), les sièges Business Builder coûtent 50 $/utilisateur/mois en facturation annuelle (65 $ en facturation mensuelle), et la tarification Enterprise est personnalisée."}, {"q": "Retool est-il un outil no-code ?", "a": "Retool est low-code plutôt que no-code. Il nécessite certaines connaissances techniques — se connecter à des bases de données, écrire des requêtes SQL et comprendre les API. Il est conçu pour les développeurs et les équipes techniques, pas pour les utilisateurs métier sans compétences techniques."}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'fr';

UPDATE tools SET best_for = $x$Criar ferramentas e aplicativos internos de IA sobre bancos de dados e APIs$x$
 WHERE slug = 'retool-ai' AND lang = 'pt';

UPDATE tools SET description = $x$Plataforma low-code para criar ferramentas internas de negócios — dashboards, painéis administrativos, editores de dados — com componentes de IA e fluxos de trabalho agênticos. O plano gratuito cobre até 5 usuários; os planos pagos separam assentos de Builder e de Internal User, cobrados mensal ou anualmente (assentos Team Builder $10/mês anual ou $12/mês mensal; assentos Business Builder $50/mês anual ou $65/mês mensal).$x$
 WHERE slug = 'retool-ai' AND lang = 'pt';

UPDATE tools SET description_long = $x$Retool é uma plataforma de desenvolvimento low-code para criar aplicações internas de negócios — painéis administrativos, dashboards de dados, ferramentas de suporte ao cliente e fluxos de trabalho operacionais — conectando-se diretamente a bancos de dados e APIs.

A partir de 2026, a Retool organiza sua plataforma em torno de Agents, Workflows e Apps. Os Retool Agents agora são um complemento distinto para agentes autônomos que lidam com suporte ao cliente, análise de dados e automação de processos, cobrados por hora e separadamente dos créditos de IA incluídos em cada plano. O "Retool AI" agora funciona como uma descrição geral desses recursos de IA, em vez de uma linha de produtos separada.

O Retool AI permite que as equipes incorporem componentes baseados em LLM aos aplicativos: preenchimento automático de formulários com IA, resumo de dados com IA, chatbots de IA dentro de dashboards internos e fluxos de trabalho agênticos que encadeiam múltiplas etapas de IA com pontos de aprovação humana (human-in-the-loop). A plataforma se conecta a fontes de dados incluindo Postgres, MySQL, Snowflake, MongoDB, APIs REST e GraphQL. O construtor de arrastar e soltar cria interfaces, enquanto componentes pré-construídos lidam com padrões comuns. Os principais recursos incluem um construtor visual de aplicativos, conexões com bancos de dados e APIs, componentes de IA (geração de texto por LLM, assistentes de IA para formulários), um construtor de fluxos de trabalho agênticos com etapas de aprovação humana, suporte a JavaScript e Python para lógica personalizada, logs de auditoria e controle de acesso baseado em funções.

O plano gratuito da Retool cobre até 5 usuários com aplicativos web e móveis ilimitados, mas é limitado por uso: 500 execuções de fluxo de trabalho por mês, 5GB de capacidade de banco de dados, 5GB de armazenamento de arquivos, 250 créditos de IA por mês e até 20 horas de agente por mês. Os planos pagos separam os assentos de Builder (pessoas que criam aplicativos) dos assentos mais baratos de Internal User (pessoas que apenas os utilizam). Os assentos Team Builder custam $10 por usuário por mês faturados anualmente ou $12 faturados mensalmente; os assentos Team Internal User custam $5 por usuário por mês anualmente ou $7 mensalmente. Os assentos Business Builder custam $50 por usuário por mês anualmente ou $65 mensalmente; os assentos Business Internal User custam $15 por usuário por mês anualmente ou $18 mensalmente. O preço do Enterprise é personalizado. Os Retool Agents são cobrados separadamente por hora, a taxas que variam conforme a capacidade do modelo, com uma franquia gratuita de até 20 horas de agente por mês incluída em todos os planos.

O Retool é otimizado para ferramentas internas — não é adequado para criar aplicativos de produção voltados ao cliente. Os agentes de IA são cobrados por hora além dos custos por assento, o que pode dificultar a previsão do gasto total para equipes que usam agentes intensamente. O construtor visual, embora poderoso para o caso de uso da Retool, exige familiaridade com conceitos de dados (consultas, transformações) para ser usado com eficácia.

Mais adequado para equipes de operações, produto e engenharia em startups e empresas que precisam criar ferramentas internas personalizadas sobre suas fontes de dados existentes — particularmente aquelas que estão adicionando fluxos de trabalho assistidos por IA às operações de negócios já existentes.$x$
 WHERE slug = 'retool-ai' AND lang = 'pt';

UPDATE tools SET pros = ARRAY[$x$O construtor low-code reduz o tempo de desenvolvimento de ferramentas internas de semanas para dias$x$, $x$Conecta-se diretamente a bancos de dados (Postgres, MySQL, Snowflake, MongoDB) e APIs (REST, GraphQL) sem trabalho de backend personalizado$x$, $x$Os componentes de IA permitem recursos baseados em LLM em aplicativos internos sem desenvolvimento de IA personalizado$x$, $x$O plano gratuito para até 5 usuários inclui créditos de IA e horas de agente, não apenas a criação básica de aplicativos$x$, $x$Pontos de aprovação humana (human-in-the-loop) para fluxos de trabalho de agentes de IA$x$]::text[]
 WHERE slug = 'retool-ai' AND lang = 'pt';

UPDATE tools SET cons = ARRAY[$x$Não é adequado para aplicativos de produção voltados ao cliente$x$, $x$Os Retool Agents são cobrados separadamente por hora além de uma franquia gratuita de 20 horas/mês, adicionando um custo imprevisível ao preço por assento$x$, $x$Exige conhecimento de consultas de dados para ser usado com eficácia — não é verdadeiramente no-code$x$, $x$O preço separa assentos de Builder e Internal User nos planos Team e Business, adicionando complexidade às estimativas de custo$x$, $x$Os assentos Business Builder custam $65/usuário/mês faturados mensalmente ($50/usuário/mês se faturados anualmente), caro para equipes maiores$x$]::text[]
 WHERE slug = 'retool-ai' AND lang = 'pt';

UPDATE tools SET choose_if = $x$["✅ Você cria ferramentas internas — painéis administrativos, dashboards com ações, aplicativos CRUD para sua equipe", "✅ Você precisa não apenas exibir dados, mas realizar ações: editar registros, executar consultas, acionar fluxos de trabalho", "✅ Você se conecta diretamente a bancos de dados (PostgreSQL, MySQL, MongoDB) e APIs internas", "✅ Você é um desenvolvedor ou equipe técnica criando software interno personalizado rapidamente"]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "O que é o Retool?", "a": "Retool é uma plataforma low-code para criar ferramentas internas. Desenvolvedores se conectam a bancos de dados e APIs, e então criam painéis administrativos, dashboards e aplicativos CRUD usando componentes de arrastar e soltar. Diferentemente de dashboards, os aplicativos do Retool podem realizar ações — editar registros de banco de dados, acionar fluxos de trabalho, enviar dados."}, {"q": "O Retool é gratuito?", "a": "O Retool tem um plano gratuito para até 5 usuários, mas é limitado por uso: 500 execuções de fluxo de trabalho, 5GB de capacidade de banco de dados, 5GB de armazenamento de arquivos, 250 créditos de IA e até 20 horas de agente por mês. Os planos pagos separam assentos de Builder e de Internal User: os assentos Team Builder custam $10/usuário/mês faturados anualmente ($12/usuário/mês faturados mensalmente), os assentos Business Builder custam $50/usuário/mês anualmente ($65 mensalmente), e o preço do Enterprise é personalizado."}, {"q": "O Retool é uma ferramenta no-code?", "a": "O Retool é low-code, não no-code. Ele exige algum conhecimento técnico — conectar-se a bancos de dados, escrever consultas SQL e entender APIs. É voltado para desenvolvedores e equipes técnicas, não para usuários de negócios sem formação técnica."}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'pt';

