 WHERE slug = 'whimsical-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "¿Qué es Whimsical?", "a": "Whimsical es una herramienta de colaboración visual para crear diagramas de flujo, mapas mentales, wireframes y tableros de notas adhesivas. Whimsical AI puede generar diagramas a partir de indicaciones de texto usando una asignación de créditos medida incluida en cada plan. Es popular para la planificación de productos, el mapeo de flujos de usuario y las sesiones de lluvia de ideas."}, {"q": "¿Es Whimsical gratuito?", "a": "Whimsical tiene un plan gratuito con tableros, documentos, equipos e invitados ilimitados, pero el contenido está limitado a 50 objetos de tablero y 50 bloques de documento al mes, con exportaciones con marca de agua y 10 créditos de IA. Pro comienza en $10 por editor al mes facturado anualmente ($12 por editor al mes facturado mensualmente) para contenido ilimitado y exportaciones sin marca de agua. Business comienza en $20 por editor al mes facturado anualmente ($24 por editor al mes facturado mensualmente) y añade SSO y controles de administración."}, {"q": "¿Cuál es la diferencia entre Whimsical y Miro?", "a": "Ambas son herramientas de colaboración visual. Whimsical es más limpia y estructurada, mejor para diagramas de flujo y diagramas sistemáticos. Miro es más flexible y de lienzo infinito, mejor para sesiones de lluvia de ideas colaborativas a gran escala. Whimsical tiene una generación de diagramas por IA más sólida; Miro tiene una biblioteca de plantillas más grande."}, {"q": "¿Puede Figma reemplazar a Whimsical?", "a": "Figma puede crear diagramas de flujo y diagramas con su producto FigJam (una herramienta de pizarra). Para flujos de UX y planificación temprana, FigJam se superpone con Whimsical. Sin embargo, las herramientas de diagramación dedicadas de Whimsical y su generación por IA son más especializadas. Muchos equipos usan Whimsical para la planificación y Figma para el diseño."}]$x$::jsonb
 WHERE slug = 'whimsical-ai' AND lang = 'es';

