UPDATE tools SET faq = $x$[{"q": "Что такое Whimsical?", "a": "Whimsical — это инструмент визуального взаимодействия для создания блок-схем, диаграмм связей, каркасов интерфейсов и досок со стикерами. Whimsical AI может генерировать диаграммы из текстовых запросов, используя дозируемый лимит кредитов, включённый в каждый план. Он популярен для планирования продукта, картирования пользовательских сценариев и мозговых штурмов."}, {"q": "Whimsical бесплатный?", "a": "У Whimsical есть бесплатный план с неограниченным количеством досок, документов, команд и гостей, но контент ограничен 50 объектами на доске и 50 блоками документов в месяц, с экспортом с водяными знаками и 10 кредитами ИИ. Pro начинается с $10 за редактора в месяц при ежегодной оплате ($12 за редактора в месяц при ежемесячной оплате) для неограниченного контента и экспорта без водяных знаков. Business начинается с $20 за редактора в месяц при ежегодной оплате ($24 за редактора в месяц при ежемесячной оплате) и добавляет SSO и административные элементы управления."}, {"q": "В чём разница между Whimsical и Miro?", "a": "Оба инструмента предназначены для визуального взаимодействия. Whimsical более чистый и структурированный — лучше подходит для блок-схем и систематических диаграмм. Miro более гибкий, с бесконечным холстом — лучше подходит для крупных совместных мозговых штурмов. У Whimsical сильнее генерация диаграмм с помощью ИИ; у Miro больше библиотека шаблонов."}, {"q": "Может ли Figma заменить Whimsical?", "a": "Figma может создавать блок-схемы и диаграммы с помощью своего продукта FigJam (инструмент для доски). Для пользовательских сценариев и раннего планирования FigJam пересекается с Whimsical. Однако специализированные инструменты для диаграмм и генерация ИИ в Whimsical более узконаправлены. Многие команды используют Whimsical для планирования, а Figma — для дизайна."}]$x$::jsonb
 WHERE slug = 'whimsical-ai' AND lang = 'ru';

