UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Whimsical ?", "a": "Whimsical est un outil de collaboration visuelle permettant de créer des organigrammes, cartes mentales, wireframes et tableaux de notes autocollantes. Whimsical AI peut générer des diagrammes à partir d'invites textuelles en utilisant une allocation de crédits mesurée incluse dans chaque formule. Il est populaire pour la planification produit, la cartographie de parcours utilisateur et les sessions de brainstorming."}, {"q": "Whimsical est-il gratuit ?", "a": "Whimsical propose une formule gratuite avec tableaux, documents, équipes et invités illimités, mais le contenu est plafonné à 50 objets de tableau et 50 blocs de document par mois, avec des exports filigranés et 10 crédits IA. Pro débute à 10 $ par éditeur et par mois facturé annuellement (12 $ par éditeur et par mois facturé mensuellement) pour un contenu illimité et des exports sans filigrane. Business débute à 20 $ par éditeur et par mois facturé annuellement (24 $ par éditeur et par mois facturé mensuellement) et ajoute le SSO et des contrôles administrateur."}, {"q": "Quelle est la différence entre Whimsical et Miro ?", "a": "Les deux sont des outils de collaboration visuelle. Whimsical est plus épuré et structuré — mieux adapté aux organigrammes et diagrammes systématiques. Miro est plus flexible avec un canevas infini — mieux adapté aux grandes sessions de brainstorming collaboratif. Whimsical dispose d'une génération de diagrammes par IA plus poussée ; Miro possède une bibliothèque de modèles plus vaste."}, {"q": "Figma peut-il remplacer Whimsical ?", "a": "Figma peut créer des organigrammes et diagrammes avec son produit FigJam (un outil de tableau blanc). Pour les parcours UX et la planification précoce, FigJam se recoupe avec Whimsical. Cependant, les outils de diagramme dédiés et la génération par IA de Whimsical sont plus spécialisés. De nombreuses équipes utilisent Whimsical pour la planification et Figma pour la conception."}]$x$::jsonb
 WHERE slug = 'whimsical-ai' AND lang = 'fr';

