UPDATE tools SET faq = $x$[{"q": "O que é o Whimsical?", "a": "Whimsical é uma ferramenta de colaboração visual para criar fluxogramas, mapas mentais, wireframes e quadros de notas adesivas. O Whimsical AI pode gerar diagramas a partir de prompts de texto usando uma cota de créditos medida, incluída em todos os planos. É popular para planejamento de produto, mapeamento de fluxos de usuário e sessões de brainstorming."}, {"q": "O Whimsical é gratuito?", "a": "O Whimsical tem um plano gratuito com quadros, documentos, equipes e convidados ilimitados, mas o conteúdo é limitado a 50 objetos de quadro e 50 blocos de documento por mês, com exportações com marca d'água e 10 créditos de IA. O Pro começa em $10 por editor por mês na cobrança anual ($12 por editor por mês na cobrança mensal) para conteúdo ilimitado e exportações sem marca d'água. O Business começa em $20 por editor por mês na cobrança anual ($24 por editor por mês na cobrança mensal) e adiciona SSO e controles administrativos."}, {"q": "Qual é a diferença entre Whimsical e Miro?", "a": "Ambas são ferramentas de colaboração visual. O Whimsical é mais limpo e estruturado — melhor para fluxogramas e diagramas sistemáticos. O Miro é mais flexível e tem canvas infinito — melhor para grandes sessões colaborativas de brainstorming. O Whimsical tem geração de diagramas por IA mais forte; o Miro tem uma biblioteca de modelos maior."}, {"q": "O Figma pode substituir o Whimsical?", "a": "O Figma pode criar fluxogramas e diagramas com seu produto FigJam (uma ferramenta de quadro branco). Para fluxos de UX e planejamento inicial, o FigJam se sobrepõe ao Whimsical. No entanto, as ferramentas dedicadas de diagramação e a geração por IA do Whimsical são mais especializadas. Muitas equipes usam o Whimsical para planejamento e o Figma para design."}]$x$::jsonb
 WHERE slug = 'whimsical-ai' AND lang = 'pt';

